// Parse AI topic pick and build full context for research + generation nodes.
const ctx = $('Fetch YVR Context').item.json;
const raw = $input.item.json?.choices?.[0]?.message?.content || '';

let pick;
try {
  const cleaned = raw.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  pick = JSON.parse(cleaned);
} catch(e) {
  // Fallback topic if AI response unparseable
  pick = {
    topic: 'best nightclubs and bars in Vancouver this weekend',
    music_type: null,
    rationale: 'Fallback — AI topic parse failed',
    suggested_tags: ['vancouver', 'nightlife', 'bars', 'clubs']
  };
}

console.log(`Topic picked: "${pick.topic}" — ${pick.rationale}`);

// Build venue list for internal linking
const venueLines = (ctx.venues || [])
  .filter(v => v.is_active)
  .map(v => `  - ${v.name} (${v.establishment_type || 'venue'}, ${v.neighbourhood || 'Vancouver'}, music: ${(v.music_types || []).join('/') || 'varied'}) → ${v.url}`)
  .join('\n');

// Merge AI suggested tags with existing site tags for GPT to choose from
const availableTags = [
  ...(ctx.existing_blog_tags || []),
  ...(pick.suggested_tags || [])
].filter((t, i, a) => a.indexOf(t) === i).join(', ');

return [{
  json: {
    topic: pick.topic,
    music_type: pick.music_type || null,
    rationale: pick.rationale,
    site_url: ctx.site_url || 'https://yvradvisory.ca',
    key_pages: ctx.key_pages || {},
    venue_list: venueLines,
    available_tags: availableTags,
    all_music_types: (ctx.all_music_types || []).join(', '),
  }
}];

