parameters.jsCode:
const topicCtx = $('Build Context').item.json;

function extractContent(nodeName) {
  try {
    const raw = $(nodeName).item.json;
    const content = raw?.choices?.[0]?.message?.content || '';
    const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    return JSON.parse(cleaned);
  } catch(e) { return null; }
}

const reddit = extractContent('Reddit Research (Perplexity)');
const web = extractContent('Web Research (Perplexity)');

let redditBrief = 'No recent Reddit data.';
if (reddit?.posts?.length) {
  const lines = reddit.posts.map(p => `• [${p.subreddit}] "${p.title}" (${p.date_approx || 'recent'}) — ${p.url}\n  Insight: ${p.key_insight}`);
  redditBrief = lines.join('\n') + (reddit.consensus ? `\n\nConsensus: ${reddit.consensus}` : '');
} else if (reddit?.consensus) {
  redditBrief = reddit.consensus;
}

let webBrief = 'No recent web data.';
if (web?.facts?.length) {
  const lines = web.facts.map(f => `• ${f.source}: ${f.insight}${f.url ? ` → ${f.url}` : ''}`);
  webBrief = lines.join('\n') + (web?.summary ? `\n\nSummary: ${web.summary}` : '');
} else if (web?.summary) {
  webBrief = web.summary;
}

const externalUrls = [
  ...(reddit?.posts || []).map(p => p.url).filter(Boolean),
  ...(web?.facts || []).map(f => f.url).filter(Boolean),
].filter((u, i, a) => u && u.startsWith('http') && a.indexOf(u) === i);

return [{
  json: {
    ...topicCtx,
    reddit_brief: redditBrief,
    web_brief: webBrief,
    external_urls: externalUrls.join('\n'),
  }
}];

